import{z as l,x as s,o as e,c as d,q as n,j as A,D as a,d as t,s as o,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"展期与库存再探","description":"","frontmatter":{"title":"展期与库存再探","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-roll-inventory-revisit.md","filePath":"quant/ft-roll-inventory-revisit.md","lastUpdated":1791413859000}'),p={name:"quant/ft-roll-inventory-revisit.md"};function h(u,E,c,C,f,m){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="展期与库存再探" tabindex="-1">展期与库存再探 <a class="header-anchor" href="#展期与库存再探" aria-label="Permalink to &quot;展期与库存再探&quot;">​</a></h1><div class="epigraph"><p>日历说哪天必须走，库存说哪天值得走；把两个变量写进同一条规则，移仓才从行政动作变成有观点的交易。</p><footer>—— Working, The Theory of the Price of Storage, AER, 1949；库存与期货溢价的证据见 Gorton, Hayashi and Rouwenhorst, Review of Finance, 2013；Ng and Pirrong, Journal of Business, 1994</footer></div><p><a href="/quant/ft-roll-execution">上一课</a>把移仓写成方案族：价差单、分腿、摊薄加触发，执行与成本表闭环。机制单元至此给了日历、成本、执行三件工具，但它们还是状态盲的——同一套规则跑在满仓年份与挤仓年份，参数不该相同。本课把主干写过的库存机制重新插回前三课：<a href="/quant/inventory-curve">库存报告与曲线</a>把库存当成曲线的状态，本课问这个状态如何改截止日、成本参数与执行方案。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态盲的日历会在最差的窗口执行。低库存、交割地仓单被注销的年份，截止日附近的近月正是挤仓高发段：价差脱离仓储带、深度消失，机械摊薄把自己摊进风暴。反向的错误在深 contango 年份：高库存使远月升水接近全额持有成本，早滚等于在斜率最陡处锁价，晚滚还能收几天便宜——基准日历对此一律照旧。错在哪：把「什么时候必须走完」当成「什么时候走」，把无条件平均的价差宽度与波动当成成本表的参数。</p><p><span class="marginnote">术语翻译：「状态盲」就是规则里没写进「现在库存是高是低」这个条件。好比天气预报只告诉你本地年均降水 800 毫米，却不说今天下不下雨——平均值对今天的出行毫无用处，无条件平均的成本参数对这一期的移仓也毫无用处。</span></p><p>第二层是「相关库存」的识别。<a href="/quant/inventory-curve">库存报告与曲线</a>已警告：全国周报不等于交割地库存，总库存不等于注册仓单。近月的挤仓风险跟着交割地可交割供给走。用错状态变量，调整方向整个反掉。</p><h3 id="各板块的状态变量" tabindex="-1">各板块的状态变量 <a class="header-anchor" href="#各板块的状态变量" aria-label="Permalink to &quot;各板块的状态变量&quot;">​</a></h3><p>商品读交割地库存与注册仓单，金属加读仓单注销率；国债期货没有库存报告，对应物是 CTD 券的回购特殊性与可获得量，见<a href="/quant/ctd-cheapest">最便宜可交割</a>——可交割供给紧，近月对空头的交割选项贬值；股指期货读分红剩余与贴水分位，见<a href="/quant/cn-stockindex-basis">股指期货与贴水</a>。同一个「可交割供给紧张」的抽象，落在三个板块是三套数据。</p><p><span class="marginnote">仓单注销（cancelled warrant）是挤仓前最便宜的信号：注销意味着有人把仓单转成提货意向。LME 市场惯用注销仓单占仓单比例做近月预警，比看总库存提前数日。</span></p><p><span class="marginnote">数字实例：某金属注册仓单共 10 万吨，注销比例从 5% 升到 25%，等于 2 万吨实货转成提货意向——可交割供给一夜少了五分之一，近月挤仓概率随之跳升。这比等下一期库存周报提前好几天。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把状态写成第三张表：每品种列出状态变量、数据源与更新频率、分位口径（相对季节调整后的历史），然后三条调整规则。其一，截止日调整：可交割供给低于阈值分位，截止日提前；供给充裕且曲线深 contango，允许在窗口内后置。其二，成本参数调整：成本表按状态分桶取参——紧张状态下价差波动与宽度按高桶计，上一课的择时方差项随之放大，最优窗口自动变短。其三，方案调整：紧张状态禁用拖延式摊薄，改用<a href="/quant/ft-roll-execution">移仓的执行</a>的价差触发加降级路径。</p>',13)),(e(),A(i,null,{default:a(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8A%B6%E6%80%81%E8%A1%A8%EF%BC%9A%E4%BA%A4%E5%89%B2%E5%9C%B0%E5%BA%93%E5%AD%98%20%2F%20%E4%BB%93%E5%8D%95%E6%B3%A8%E9%94%80%20%2F%20CTD%20%E7%89%B9%E6%AE%8A%E6%80%A7%20%2F%20%E8%B4%B4%E6%B0%B4%E5%88%86%E4%BD%8D%22%5D%20--%3E%20R1%5B%22%E6%88%AA%E6%AD%A2%E6%97%A5%E8%B0%83%E6%95%B4%EF%BC%9A%E7%B4%A7%E5%BC%A0%E6%8F%90%E5%89%8D%EF%BC%8C%E5%AE%BD%E6%9D%BE%E5%90%8E%E7%BD%AE%22%5D%0A%20%20ST%20--%3E%20R2%5B%22%E6%88%90%E6%9C%AC%E5%8F%82%E6%95%B0%E6%8C%89%E7%8A%B6%E6%80%81%E5%88%86%E6%A1%B6%22%5D%0A%20%20ST%20--%3E%20R3%5B%22%E6%89%A7%E8%A1%8C%E6%96%B9%E6%A1%88%EF%BC%9A%E7%B4%A7%E5%BC%A0%E7%A6%81%E7%94%A8%E6%8B%96%E5%BB%B6%E5%BC%8F%E6%91%8A%E8%96%84%22%5D%0A%20%20R1%20--%3E%20PLAN%5B%22%E7%8A%B6%E6%80%81%E5%8C%96%E5%B1%95%E6%9C%9F%E6%96%B9%E6%A1%88%22%5D%0A%20%20R2%20--%3E%20PLAN%0A%20%20R3%20--%3E%20PLAN%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"机制仍是 Working 的仓储函数 \\(\\partial y/\\partial I\\lt 0\\)：库存低，便利收益高，近月相对远月贵且对冲击敏感——同样的意外能让价差走更远，Ng 与 Pirrong 在金属上写的就是低库存、高价差波动这一通道。读成执行语言：紧张状态下，晚滚持有的不是「等待期权」，而是「挤仓空头的空头」——你在最贵的深度里排队。Gorton、Hayashi 与 Rouwenhorst 的证据补上另一层：库存分位还改变展期收益的条件期望，所以状态不只改「怎么走」，也改「该不该持有近月」——深贴水、低库存时近月的展期收益值得多持几天，contango 高企时近月只是负 carry 的载体。三条规则是同一机制在日历、成本、执行三个表面的投影。",-1)),(e(),A(i,null,{default:a(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E5%BA%93%E5%AD%98%E4%BD%8E%EF%BC%9A%E4%BA%A4%E5%89%B2%E5%9C%B0%E5%8F%AF%E4%BA%A4%E5%89%B2%E4%BE%9B%E7%BB%99%E7%B4%A7%E5%BC%A0%22%5D%20--%3E%20HY%5B%22%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%20y%20%E4%B8%8A%E5%8D%87%EF%BC%9A%E2%88%82y%2F%E2%88%82I%20%E5%B0%8F%E4%BA%8E%200%22%5D%0A%20%20HY%20--%3E%20NEAR%5B%22%E8%BF%91%E6%9C%88%E7%9B%B8%E5%AF%B9%E8%BF%9C%E6%9C%88%E6%9B%B4%E8%B4%B5%EF%BC%9A%E6%B7%B1%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20NEAR%20--%3E%20V1%5B%22%E4%BB%B7%E5%B7%AE%E6%B3%A2%E5%8A%A8%E5%8D%87%E9%AB%98%EF%BC%9A%E5%90%8C%E6%A0%B7%E7%9A%84%E6%84%8F%E5%A4%96%E8%B5%B0%E5%BE%97%E8%BF%9C%22%5D%0A%20%20NEAR%20--%3E%20V2%5B%22%E6%B7%B1%E5%BA%A6%E5%8F%98%E8%96%84%EF%BC%9A%E5%90%8C%E6%A0%B7%E7%9A%84%E9%87%8F%E6%8E%A8%E5%BE%97%E6%9B%B4%E7%8B%A0%22%5D%0A%20%20V1%20--%3E%20LATE%5B%22%E6%99%9A%E6%BB%9A%EF%BC%9A%E5%9C%A8%E6%9C%80%E8%B4%B5%E7%9A%84%E6%B7%B1%E5%BA%A6%E9%87%8C%E6%8E%92%E9%98%9F%22%5D%0A%20%20V2%20--%3E%20LATE%0A%20%20LATE%20--%3E%20FIX%5B%22%E8%A7%84%E5%88%99%E5%9B%9E%E5%BA%94%EF%BC%9A%E6%88%AA%E6%AD%A2%E6%97%A5%E6%8F%90%E5%89%8D%20%2B%20%E7%A6%81%E6%8B%96%E5%BB%B6%E5%BC%8F%E6%91%8A%E8%96%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">直觉类比：库存是市场的减震器。满仓年份，一次供给意外被库存垫住，价差晃一下就回来；低库存年份减震器没了，同样的冲击直接把近月价差颠飞——「低库存、高价差波动」说的就是这条通道。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>状态数据滞后：库存周报、仓单日频但披露有时滞，分位要在 vintage 上算，否则回测用了未来数据。别过度反应：一次库存意外不是挤仓前兆，阈值分位过滤的是持续状态。政策库存（战略储备释放）不进商业仓单逻辑，<a href="/quant/inventory-curve">库存报告与曲线</a>已单列。也别把「库存」扩到没有库存的市场：指数与利率期货用的是各自的可交割供给代理，硬套仓储公式是把隐喻当机制。本课管机制层的状态注入；策略层怎么用这些自由度，下一课进入指数展期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>日历、成本、执行三件工具都要状态化：截止日、分桶参数、方案约束随库存状态调整。</li><li>状态变量按板块选对：交割地库存与仓单（商品）、CTD 特殊性（国债）、贴水与分红剩余（股指）。</li><li>机制是 \\(\\partial y/\\partial I\\lt 0\\)：低库存使价差波动与宽度上升，晚滚等于持有负向选择权。</li><li>库存分位同时改条件展期收益——状态也回答「该不该持有近月」。</li><li>状态在 vintage 上算，阈值过滤持续状态；政策库存与无库存市场不套仓储公式。</li><li>出处：Working, <em>AER</em>, 1949；Ng and Pirrong, <em>Journal of Business</em>, 1994；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013。</li></ul>',5))])}const T=l(p,[["render",h]]);export{F as __pageData,T as default};
